async function main():Promise<void>{
 try{
  fs.mkdirSync(evidenceDir,{recursive:true});
  const now=Date.now();
  markIsolatedFolder(profileRoot,app.getPath('appData'));
  const solo=path.join(profileRoot,'solo');fs.mkdirSync(solo,{recursive:true,mode:0o700});
  const seed=fixtureProfile(now);
  assert.equal(seed.version,8);
  if(scenario==='fresh')assert.equal(Object.hasOwn(seed.leisure,'bonds'),false,'legacy-compatible v8 profile should not gain the optional extension while loading');
  else assert.ok(Object.hasOwn(seed.leisure,'bonds')=== (scenario==='rich'),'fixture bond extension shape');
  fs.writeFileSync(path.join(solo,'profile.json'),JSON.stringify(seed)+'\n',{flag:'wx',mode:0o600});
  const readback=new GameStore(solo,now).value;assert.deepEqual(readback,seed);profileBefore=parseProfile(readback);
  check('independent isolated profile preflight: parseProfile + GameStore readback',{scenario,folder:profileRoot,version:seed.version,sequence:seed.sequence,job:seed.job,coins:seed.coins,hasBonds:Object.hasOwn(seed.leisure,'bonds'),bondsVersion:seed.leisure.bonds?.version??null});
  if(process.platform==='darwin'){app.setActivationPolicy('prohibited');app.dock?.hide();check('macOS activation suppression',{policy:'prohibited',dockHidden:true});}
  replace(app,'focus',()=>{suppress.appFocus=(suppress.appFocus??0)+1;return false;});
  replace(Menu,'setApplicationMenu',()=>{});
  app.on('browser-window-created',(_event,win)=>patch(win));
  app.on('web-contents-created',(_event:any,contents:any)=>contents.on('console-message',(event:any)=>{if(event.level==='error')errors.push(String(event.message).slice(0,500));}));
  shell=await startDesktop(profileRoot,true);overlay=shell.overlay;
  await until(()=>js<boolean>(overlay!,'document.body.dataset.atlas==="verified"&&!!document.getElementById("dungeonSign")'),'hidden overlay ready');
  await until(()=>shell!.game.state.status==='ready'&&shell!.game.state.profile?.version===8,'v8 worker ready');
  assert.equal(overlay.isVisible(),false);assert.equal(overlay.isFocused(),false);assert.equal(currentProfile().version,8);assertSameExceptClock(seed,currentProfile(),'worker startup may advance only the natural clock before user input');
  check('hidden isolated shell and scenario profile ready',{scenario,overlay:{isVisible:overlay.isVisible(),isFocused:overlay.isFocused()},version:currentProfile().version,hasBonds:Object.hasOwn(currentProfile().leisure,'bonds')});
  let win=await clickPortal();
  if(scenario==='fresh')await freshSmoke(win);
  else if(scenario==='recruit')await recruitScenario(win);
  else await richScenario(win);
  if(shell.arenaWindow&&!shell.arenaWindow.isDestroyed()){
   win=shell.arenaWindow;await closeArenaViaButton(win,'scenario final close');
  }
  assert.equal(errors.length,0,`renderer console errors: ${errors.join('; ')}`);
  assert.equal(suppress.globalShortcut??0,0,'global shortcuts must remain unused');
  for(const row of snapshots())assert.equal(row.isVisible,false,`window became visible: ${JSON.stringify(row)}`);
  await shell.game.request('flush');assert.deepEqual(new GameStore(solo).value,currentProfile(),'only the isolated scenario profile is persisted');
  assert.deepEqual(hashesAtStart,hashFiles(),'candidate/source bytes must remain unchanged during the native scenario');
  status='PASS';check('hidden native scenario completed',{scenario,profileFile:path.join(solo,'profile.json'),keyboardEvents:keyboardEventTotal,globalShortcut:suppress.globalShortcut??0,rendererConsoleErrors:errors.length,nativeWindows:snapshots(),hashesUnchanged:true});
 }catch(e){status='FAIL';errors.push(String(e));report(e);console.error(e instanceof Error?e.stack:String(e));}
 finally{if(shell?.arenaWindow&&!shell.arenaWindow.isDestroyed())try{shell.closeArena();}catch{}report(status==='FAIL'?new Error(errors.at(-1)||'failure'):undefined);app.quit();}
}
void main();
